package app.kinnect.live;
import android.content.Context;import android.graphics.Typeface;
final class ApprovedTypography {static Typeface normal,bold;static Typeface font(Context c,int style){if(normal==null)normal=c.getResources().getFont(c.getResources().getIdentifier("kinnect_regular","font",c.getPackageName()));if(bold==null)bold=c.getResources().getFont(c.getResources().getIdentifier("kinnect_semibold","font",c.getPackageName()));return Typeface.create((style&Typeface.BOLD)!=0?bold:normal,style);}
 static void sheet(android.view.View view){if(view instanceof android.widget.TextView){android.widget.TextView text=(android.widget.TextView)view;String value=text.getText().toString();if(value.codePoints().anyMatch(Character::isLetterOrDigit)||text instanceof android.widget.EditText){int style=text.getTypeface()==null?Typeface.NORMAL:text.getTypeface().getStyle();text.setTypeface(font(view.getContext(),style));float size=text.getTextSize()/view.getResources().getDisplayMetrics().scaledDensity;float max="sheet:title".equals(text.getTag())?16:text instanceof android.widget.EditText?14:13;if(size>max)text.setTextSize(max);}}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)sheet(group.getChildAt(i));}}
}
